import{_ as a,o as s,c as t,a2 as n}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"调试","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dev/debugging.md","filePath":"zh/dev/debugging.md"}'),o={name:"zh/dev/debugging.md"};function l(i,e,c,d,p,r){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="调试" tabindex="-1">调试 <a class="header-anchor" href="#调试" aria-label="Permalink to &quot;调试&quot;">​</a></h1><h2 id="先读启动日志" tabindex="-1">先读启动日志 <a class="header-anchor" href="#先读启动日志" aria-label="Permalink to &quot;先读启动日志&quot;">​</a></h2><p>每个子系统在点亮时都会打印一行 <code>.... OK</code>。最后一条没有打印出来的，就是你的故障子系统。捕获它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 -m 512 -cdrom build/opencube.iso \\</span></span>
<span class="line"><span>    -serial file:boot.log -display none</span></span></code></pre></div><h2 id="客户机内工具" tabindex="-1">客户机内工具 <a class="header-anchor" href="#客户机内工具" aria-label="Permalink to &quot;客户机内工具&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; dmesg            (kernel ring buffer)</span></span>
<span class="line"><span>oc&gt; logcat           (live follow of the persistent log)</span></span>
<span class="line"><span>oc&gt; logctl           (log levels + filters)</span></span>
<span class="line"><span>oc&gt; health           (CPU/mem/tasks/IO + alarms)</span></span>
<span class="line"><span>oc&gt; exc              (exception self-test - proves the trap path)</span></span>
<span class="line"><span>oc&gt; crashlog         (past crash records on /etc)</span></span>
<span class="line"><span>oc&gt; dumpinfo         (crash dump details)</span></span></code></pre></div><h2 id="panic-路径" tabindex="-1">panic 路径 <a class="header-anchor" href="#panic-路径" aria-label="Permalink to &quot;panic 路径&quot;">​</a></h2><p>内核 panic 会把异常现场（寄存器 + 故障地址）转储到串口，并向 /etc 写入一条崩溃日志。<code>crashtest</code> 会故意触发一次——用它来验证你的 /etc 卷与串口捕获在真正需要之前就已接好。</p><h2 id="宿主侧调试内核" tabindex="-1">宿主侧调试内核 <a class="header-anchor" href="#宿主侧调试内核" aria-label="Permalink to &quot;宿主侧调试内核&quot;">​</a></h2><ul><li>调试符号：流水线先带 <code>-g</code> 链接、再对最终 ELF 做 strip；<code>build/opencube_base.elf</code>（<code>strip</code> 之前、在 <code>make kernel</code> 过程中产出）就是你的符号载体。</li><li>在 QEMU 里：<code>-d int,cpu_reset -D qemu.log</code> 记录中断与复位；<code>-s -S</code> 配合 gdb（<code>target remote localhost:1234</code>）就是经典的远程调试回路。</li><li>可复现构建意味着同一崩溃复现两次就是<em>同一份字节</em>——不会在重试之间出现“海森堡构建”。</li></ul><h2 id="宿主单元测试" tabindex="-1">宿主单元测试 <a class="header-anchor" href="#宿主单元测试" aria-label="Permalink to &quot;宿主单元测试&quot;">​</a></h2><p><code>make test</code> 会在宿主编译器上针对真实内核源码编译并运行 <code>tests/host_*.c</code> 下的测试架（加密向量、tar、gzip、字符串、FAT 结构、带 ASAN 的 mbi 解析）。在这里回归，比反复启动虚拟机迭代快得多。</p><h2 id="已知的锋利边缘-来自审计记录" tabindex="-1">已知的锋利边缘（来自审计记录） <a class="header-anchor" href="#已知的锋利边缘-来自审计记录" aria-label="Permalink to &quot;已知的锋利边缘（来自审计记录）&quot;">​</a></h2><ul><li>高于 4 GiB 的 xHCI DMA 会在探测与每次传输时被拒绝——如果 xHCI 设备消失，先检查你的 QEMU 内存大小。</li><li>ATA-DMA 对齐依赖堆的 32 字节块头；如果你动了 <code>mem_heap.c</code>，请运行 <code>fstest</code> 外加一次 FAT32 挂载测试。</li><li>multiboot2 解析器会校验 tag 尺寸；测试里“手搓”的 mbi 必须遵守每个 tag 的最小值，否则解析会提前停止。</li></ul>`,14)])])}const g=a(o,[["render",l]]);export{u as __pageData,g as default};
